lemma Basis.equivFun_symm_eq_repr_symm {M ι R : Type*}
    [Fintype ι] [AddCommMonoid M] [Semiring R] [Module R M] (b : Basis ι R M) (f : ι →₀ R) :
    b.equivFun.symm f = b.repr.symm f

lemma pi_dvd_iff_mod_zero {K R: Type*} [CommRing R] [CommRing K] {q : R →+* K }
    {π : R} (hqker : RingHom.ker q = Ideal.span {π}) (T : Polynomial R) :
    C π ∣ T ↔ map q T = 0

lemma self_isRadicalPart_of_coprime {p n : ℕ}
    (f : Polynomial <| ZMod p) (hgcd : ∃ a b ,  a * f + b * (derivative f) = n)
    (hc : n.Coprime p) : IsRadicalPart f f

theorem LinearIndependent.mapₛₗ {v : ι → M} {f : M →ₛₗ[g] N}
    (hf_inj : Submodule.comap (Finsupp.linearCombination R v) (LinearMap.ker f) ≤ RingHom.ker g • ⊤) :
    LinearIndependent S (f ∘ v)

theorem resultant_map_injective {S R : Type*} [CommRing R] [CommRing S] {φ : R →+* S}
    (hφ : Function.Injective φ) (f g : R[X]) :
    resultant (f.map φ) (g.map φ) = φ (resultant f g)

lemma neg_of_ne_zero_of_exists_neg (hc : IsRealClosedField F) {a b m : F} {P : F[X]}
    (hP : ∀ x ∈ Ioo a b , P.eval x ≠ 0) (hm : m ∈ Ioo a b) (hneg : P.eval m < 0) :
    ∀ x ∈ Ioo a b , P.eval x < 0

lemma nonneg_of_ne_zero_of_exists_pos (hc : IsRealClosedField F) {a b m : F} {P : F[X]}
    (hP : ∀ x ∈ Ioo a b , P.eval x ≠ 0) (hm : m ∈ Ioo a b) (hpos : P.eval m > 0) :
    ∀ x ∈ Icc a b , P.eval x ≥ 0

lemma nonpos_of_ne_zero_of_exists_neg (hc : IsRealClosedField F) {a b m : F} {P : F[X]}
    (hP : ∀ x ∈ Ioo a b , P.eval x ≠ 0) (hm : m ∈ Ioo a b) (hneg : P.eval m < 0) :
    ∀ x ∈ Icc a b , P.eval x ≤ 0

lemma pos_of_ne_zero_of_exists_pos (hc : IsRealClosedField F) {a b m : F} {P : F[X]}
    (hP : ∀ x ∈ Ioo a b , P.eval x ≠ 0) (hm : m ∈ Ioo a b) (hpos : P.eval m > 0) :
    ∀ x ∈ Ioo a b , P.eval x > 0

lemma not_mem_finset_card_eq_one_of_sorted_mem_interval {a b d u v : F} {as : List F}
  {S : Finset F}  (heqc : (u :: v :: as) = ((S.filter (fun x => x ∈ Icc a b)).sort (fun x y => x ≤ y)))
  (hle1 : u < d) (hle2 : d < v) : d ∈ Icc a b

lemma not_mem_finset_card_eq_one_of_sorted_single {a b u : F} {S : Finset F}
  (heq : [u] = ((S.filter (fun x => x ∈ Icc a b)).sort (fun x y => x ≤ y)) )
  (x : F) : x ∈ (S.filter (fun x => x ∈ Icc a b)) ↔ x = u
